sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cellSize;
uniform float aspect;
uniform float shape;
uniform float gap;
layout(color) uniform half4 gapColor;
uniform float colorLevels;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 cell = float2(max(cellSize * aspect, 1.0), max(cellSize, 1.0));
    float2 g = coord / cell;
    float4 px = tex((floor(g) + 0.5) * cell);
    float2 lp = (fract(g) - 0.5) * 2.0;
    float edge = 1.0 - gap;
    float m = step(max(abs(lp.x), abs(lp.y)), edge);
    if (shape > 0.5 && shape < 1.5) m = 1.0 - smoothstep(edge - 0.1, edge, length(lp));
    else if (shape > 1.5) m = 1.0 - smoothstep(edge * 1.4 - 0.1, edge * 1.4, abs(lp.x) + abs(lp.y));
    float3 s = unp(px);
    if (colorLevels >= 2.0) s = floor(s * (colorLevels - 1.0) + 0.5) / (colorLevels - 1.0);
    float3 col = mix(float3(gapColor.rgb), s, m);
    return fin(c, float4(col * px.a, px.a), opacity);
}
